window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-organization-tags.html"]="<!-- Settings: Organisasi — Tag -->\n<style>\n.st-tag-bar{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:20px}\n.st-tag-chip{display:inline-flex;align-items:center;gap:6px;padding:6px 14px;border-radius:16px;font-size:13px;font-weight:500;background:var(--accent);color:#fff}\n.st-tag-chip .x{cursor:pointer;font-size:15px;font-weight:700;opacity:.7}\n.st-tag-chip .x:hover{opacity:1}\n.st-tag-add{display:flex;gap:8px;max-width:400px}\n.st-tag-add input{flex:1;padding:8px 12px;border:1px solid var(--border);border-radius:8px;font-size:13px;background:var(--bg)}\n.st-tag-add input:focus{outline:2px solid var(--accent);outline-offset:-1px}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\" id=\"stNav\"></aside>\n  <div class=\"settings-body\">\n    <h2 style=\"margin-bottom:4px\">Tag</h2>\n    <p style=\"font-size:13px;color:var(--muted);margin-bottom:20px\">Tag digunakan untuk mengelompokkan kontak dan percakapan.</p>\n\n    <div class=\"card\">\n      <div class=\"st-tag-bar\" id=\"tagBar\"></div>\n      <div class=\"st-tag-add\">\n        <input type=\"text\" id=\"tagInput\" placeholder=\"Tambah tag baru…\" onkeydown=\"if(event.key==='Enter')addTag()\">\n        <button class=\"btn primary\" onclick=\"addTag()\">+ Tambah</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.getElementById('stNav').innerHTML=renderSettingsNav('organization-tags');\n\n  function render(){\n    const bar=document.getElementById('tagBar');\n    if(!DB.settings.tags.length){bar.innerHTML='<span style=\"color:var(--muted);font-size:13px\">Belum ada tag.</span>';return}\n    bar.innerHTML=DB.settings.tags.map((t,i)=>`<span class=\"st-tag-chip\">${t} <span class=\"x\" onclick=\"removeTag(${i})\">×</span></span>`).join('');\n  }\n  render();\n\n  window.addTag=function(){\n    const v=document.getElementById('tagInput').value.trim();\n    if(!v)return;\n    if(DB.settings.tags.includes(v)){showToast('Tag sudah ada');return}\n    DB.settings.tags.push(v);saveStore();render();\n    document.getElementById('tagInput').value='';\n    showToast('Tag ditambahkan');\n  };\n\n  window.removeTag=function(i){\n    DB.settings.tags.splice(i,1);saveStore();render();\n    showToast('Tag dihapus');\n  };\n})();\n</script>\n";
